  flashcards: [
    { front: { vi: "React là library hay framework?", en: "Is React a library or a framework?" }, back: { vi: "Là <b>library UI</b>, chỉ lo tầng view (declarative). Routing, state, fetch dữ liệu... bạn phải tự lắp thêm.", en: "It's a <b>UI library</b>, handling only the view layer (declarative). Routing, state, data fetching, etc. you bolt on yourself." } },
    { front: { vi: "Declarative nghĩa là gì trong React?", en: "What does declarative mean in React?" }, back: { vi: "Bạn viết <code>UI = f(state)</code> — mô tả UI trông thế nào với một state, không thao tác DOM từng bước. React tự lo cập nhật DOM.", en: "You write <code>UI = f(state)</code> — describe what the UI looks like for a given state, not step-by-step DOM manipulation. React handles updating the DOM." } },
    { front: { vi: "Props vs State khác nhau?", en: "Props vs State difference?" }, back: { vi: "<b>Props</b>: chỉ đọc, truyền xuống từ cha. <b>State</b>: dữ liệu nội bộ thay đổi theo thời gian; đổi state → component re-render.", en: "<b>Props</b>: read-only, passed down from the parent. <b>State</b>: internal data that changes over time; changing state re-renders the component." } },
    { front: { vi: "One-way data flow là gì?", en: "What is one-way data flow?" }, back: { vi: "Dữ liệu chảy <b>xuống</b> qua props; con báo <b>lên</b> qua callback. Dễ đoán, luôn biết state nằm ở đâu.", en: "Data flows <b>down</b> via props; children report <b>up</b> via callbacks. Predictable — you always know where state lives." } },
    { front: { vi: "JSX biên dịch thành gì?", en: "What does JSX compile to?" }, back: { vi: "Thành các lời gọi <code>React.createElement(...)</code>. JSX chỉ là cú pháp giống HTML viết trong JS.", en: "Into <code>React.createElement(...)</code> calls. JSX is just HTML-like syntax written in JS." } },
    { front: { vi: "Virtual DOM là gì?", en: "What is the Virtual DOM?" }, back: { vi: "Một cây UI nhẹ trong bộ nhớ. State đổi → React dựng cây mới và diff với cây cũ để áp thay đổi tối thiểu lên DOM thật.", en: "A lightweight in-memory UI tree. On a state change React builds a new tree and diffs it against the old to apply minimal changes to the real DOM." } },
    { front: { vi: "Reconciliation (diffing) làm gì?", en: "What does reconciliation (diffing) do?" }, back: { vi: "So cây virtual DOM mới với cây cũ để tính <b>tập thay đổi DOM thật tối thiểu</b>. Mục tiêu: giảm số lần chạm vào DOM thật (vốn chậm).", en: "Compares the new virtual DOM tree with the old to compute the <b>minimal set of real-DOM changes</b>. Goal: minimize touches to the slow real DOM." } },
    { front: { vi: "Vì sao cần prop key khi render list?", en: "Why are keys needed when rendering a list?" }, back: { vi: "Key cho React một <b>định danh ổn định</b> để khớp phần tử giữa các lần render, tránh hủy/tạo lại DOM thừa. Đừng dùng index mảng nếu list đổi thứ tự.", en: "Keys give React a <b>stable identity</b> to match elements across renders, avoiding needless DOM destroy/recreate. Don't use the array index if the list can reorder." } },
    { front: { vi: "useState dùng để làm gì?", en: "What is useState for?" }, back: { vi: "Khai báo <b>state cục bộ</b> trong function component. Gọi setter (VD <code>setCount</code>) → state đổi → component re-render.", en: "Declares <b>local state</b> in a function component. Calling the setter (e.g. <code>setCount</code>) changes state → the component re-renders." } },
    { front: { vi: "useEffect chạy khi nào? Dependency array làm gì?", en: "When does useEffect run? What does the dependency array do?" }, back: { vi: "Chạy <b>sau</b> render, dùng cho side effect (fetch, subscription, timer). <code>[]</code> = chạy 1 lần (mount); <code>[deps]</code> = chạy lại khi deps đổi. Trả về hàm <b>cleanup</b>.", en: "Runs <b>after</b> render, for side effects (fetch, subscription, timer). <code>[]</code> = run once (mount); <code>[deps]</code> = re-run when deps change. Return a <b>cleanup</b> function." } },
    { front: { vi: "useMemo vs useCallback?", en: "useMemo vs useCallback?" }, back: { vi: "<b>useMemo</b> memoize một <b>giá trị</b> tốn kém để tránh tính lại; <b>useCallback</b> memoize một <b>hàm</b> để tránh tạo lại / re-render thừa ở con.", en: "<b>useMemo</b> memoizes an expensive <b>value</b> to avoid recomputing; <b>useCallback</b> memoizes a <b>function</b> to avoid recreating it / unnecessary child re-renders." } },
    { front: { vi: "useRef khác state ở điểm nào?", en: "How does useRef differ from state?" }, back: { vi: "<code>useRef</code> giữ giá trị thay đổi được, tồn tại qua các lần render nhưng <b>không gây re-render</b> khi đổi. Hay dùng để tham chiếu DOM.", en: "<code>useRef</code> holds a mutable value that persists across renders but does <b>not trigger a re-render</b> when changed. Often used for DOM references." } },
    { front: { vi: "Rules of Hooks là gì và vì sao có?", en: "What are the Rules of Hooks and why?" }, back: { vi: "Chỉ gọi hook ở <b>top level</b> và <b>trong hàm React</b>. Vì Hooks định danh theo <b>thứ tự gọi</b>; gọi trong if/loop làm đổi thứ tự → React lẫn state.", en: "Only call hooks at the <b>top level</b> and <b>inside React functions</b>. Because Hooks are identified by <b>call order</b>; calling inside if/loop changes the order → React mixes up state." } },
    { front: { vi: "React 18+ có gì mới đáng nhắc?", en: "What's notable in React 18+?" }, back: { vi: "Concurrent rendering, automatic batching, <b>Suspense</b> (loading khai báo), <b>React Server Components</b> (render ở server, ít JS), <b>React Compiler</b> (tự memoize).", en: "Concurrent rendering, automatic batching, <b>Suspense</b> (declarative loading), <b>React Server Components</b> (server-rendered, less JS), <b>React Compiler</b> (auto-memoization)." } },
  ],
